import{d as c,C as t,o as u,c as g,j as a,a as s,E as n,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"道德经第三十章","description":"从用兵之害与果而勿强，理解济难有止和武力暴兴的限度。","frontmatter":{"title":"道德经第三十章","description":"从用兵之害与果而勿强，理解济难有止和武力暴兴的限度。","category":"guide","aliases":["道德经第三十章","老子第三十章","dao de jing chapter 30"],"source":["王弼《道德真经注》卷二"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-30.md","filePath":"daoism/dao-de-jing/chapter-30.md","lastUpdated":1794189804000}'),b={name:"daoism/dao-de-jing/chapter-30.md"},_=c({...b,setup(p){const i=[{id:"assistance-without-military-domination",label:"以道佐人主者，不以兵强天下",showLabel:!0,sentences:[["以道",{text:"佐",glossary:"zuo"},"人主者，不以兵",{text:"强",glossary:"qiang"},"天下，其事",{text:"好还",glossary:"haohuan"},"。"]],note:["【白话】用道辅佐人主的人，不凭兵力在天下逞强；这类用兵逞强之事容易招致反复、回还。依本页所循王注，处置的方向还须回返无为，不继续以立功生事。","【王弼注择要】「为始者务欲立功生事，而有道者务欲还反无为。」王弼以此解释其事好还，将有道者的取向放在收回造作，而非再兴事端。","【读法】好还常被解为用兵容易招来报复；王注此处更着重返归无为。本页并列交代两种取径，不把古注改写成因果报应的保证。"]},{id:"the-aftermath-of-war",label:"师之所处，荆棘生焉",showLabel:!0,sentences:[[{text:"师",glossary:"shi"},"之所处，",{text:"荆棘",glossary:"jingji"},"生焉；大军之后，必有",{text:"凶年",glossary:"xiongnian"},"。"]],note:["【白话】军队驻扎过的地方，荆棘丛生；大战之后，往往接着荒歉的年景。原文用必字突出战事的严重后果，所指关乎人民生计和田土荒残。","【王弼注择要】「贼害人民，残荒田亩。」王弼以具体损害说明荆棘与凶年，又说「无有所济，必有所伤」，不把战争只当作争胜者的功业。","【读法】白话以往往说明现实中的风险，不消去原句必字的警切。这里也不只是心中杂念的比喻，应先看军队、民生与生产的直接联系。"]},{id:"achieving-the-necessary-result",label:"善者果而已，不敢以取强",showLabel:!0,sentences:[["善者",{text:"果",glossary:"guo"},"而已，不敢以取强。"]],note:["【白话】善于用兵的人，只求解除患难、办成必要的事而止，不敢借战果继续取强、凌压天下。","【王弼注择要】「果，犹济也。」注进一步说「善用师者，趣以济难而已矣」，并以不取强说明止处。","【读法】本站作善者果而已，所据录文作善有果而已。果依济难理解，不能只凭获得结果四字，便把任何目的和手段都合理化。"]},{id:"restraint-after-success",label:"果而勿矜，果而勿伐",showLabel:!0,sentences:[["果而勿",{text:"矜",glossary:"jin"},"，果而勿",{text:"伐",glossary:"fa"},"，果而勿",{text:"骄",glossary:"jiao"},"，果而",{text:"不得已",glossary:"budeyi"},"，果而勿强。"]],note:["【白话】办成必要的事而不自高，不夸功，不骄纵；行动出于不得已，取得结果后也不再逞强。五个果而为成果与力量划出限制。","【王弼注择要】「吾不以师道为尚，不得已而用，何矜骄之有也。」注又说「不遂用果以为强也」，强调不能把济难所得继续化为扩张之资。","【读法】不得已在这里取迫于必要义，与第二十九章不得之句分开。矜、伐、骄针对功成后的自负夸耀；强读 qiáng，取逞强、取强义。"]},{id:"violent-strength-and-early-end",label:"物壮则老，是谓不道",showLabel:!0,sentences:[["物",{text:"壮",glossary:"zhuang"},"则老，是谓不道，不道早",{text:"已",glossary:"yi"},"。"]],note:["【白话】事物强盛过度便走向衰老，这就叫不合于道；不合于道，便会很早止尽。这里承接上文，警戒以武力暴兴、不断取强。","【王弼注择要】「壮，武力暴兴也。」注又回引「飘风不终朝，骤雨不终日」，把壮老与第二十三章暴疾难久相连。","【读法】依王弼，本章的壮先指武力暴兴，不泛指所有健康成长或适当增强。已作停止、止尽，不是已经的现代副词。"]}],o=[{id:"zuo",term:"佐",sense:1},{id:"qiang",term:"强",sense:3,pinyin:"qiáng"},{id:"haohuan",term:"好还",sense:1},{id:"shi",term:"师",sense:1},{id:"jingji",term:"荆棘",sense:1},{id:"xiongnian",term:"凶年",sense:1},{id:"guo",term:"果",sense:1},{id:"jin",term:"矜",sense:1},{id:"fa",term:"伐",sense:1},{id:"jiao",term:"骄",sense:1},{id:"budeyi",term:"不得已",sense:2},{id:"zhuang",term:"壮",sense:1},{id:"yi",term:"已",sense:1}];return(x,e)=>{const r=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),g("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第三十章",tabindex:"-1"},[s("道德经第三十章 "),a("a",{class:"header-anchor",href:"#道德经第三十章","aria-label":'Permalink to "道德经第三十章"'},"​")],-1)),n(r,{title:"以道辅佐人主，为什么不靠兵力逞强",summary:"本章先反省以兵强天下，再写战事对人民与田土的损伤；接着用果与五个限制说明用兵有止，最后以壮老收束。",points:[{label:"先读",text:"先看兵强与战后损害，保留本章具体的战争语境。"},{label:"再辨",text:"果不是不断扩大战果，王弼以济难说明应止在何处。"},{label:"后看",text:"五个果而限制自矜、夸功与逞强，再看壮字为何连到武力暴兴。"}],hint:"好还的好读 hào，还读 huán；本页说明反复报复的常见读法及王弼返归无为的取径。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),n(l,{sections:i,glossary:o}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),n(d,{lines:[{text:"师之所处，荆棘生焉；大军之后，必有凶年。",tone:"让损害进入判断",guide:"在谈功业之前，先把人民、田土与战后的持续代价纳入考虑。"},{text:"善者果而已，不敢以取强。",tone:"济难而止",guide:"果循王弼济难义，既有要完成的事，也有完成之后不再扩张的止处。"},{text:"果而勿矜，果而勿伐，果而勿骄，果而不得已，果而勿强。",tone:"功成后的五限",guide:"不只问能否办成，还问为何动用力量、怎样对待战果、何时停止。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),n(h,{items:o}),e[4]||(e[4]=m("",15))])}}});export{y as __pageData,_ as default};
